mapper.select:
SELECT f.id, f.user_id, f.user_type, CASE f.user_type WHEN 1 THEN s.nick_name WHEN 2 THEN e.enterprise_name WHEN 3 THEN a.nick_name ELSE '未知' END AS user_name, f.feedback_type, f.title, f.content, f.handle_status, CASE f.handle_status WHEN 0 THEN '待处理' WHEN 1 THEN '已处理' WHEN 2 THEN '已关闭' ELSE '未知' END AS handle_status_name, f.create_time FROM feedback f LEFT JOIN student s ON f.user_type = 1 AND f.user_id = s.id LEFT JOIN enterprise e ON f.user_type = 2 AND f.user_id = e.id LEFT JOIN admin a ON f.user_type = 3 AND f.user_id = a.id
AND f.handle_status = #{handleStatus}
AND f.feedback_type = #{feedbackType}
ORDER BY f.create_time DESC
